patch:
diff --git a/src/jrd/jrd.cpp b/src/jrd/jrd.cpp
index ed9b39e63e7..7a936a19580 100644
--- a/src/jrd/jrd.cpp
+++ b/src/jrd/jrd.cpp
@@ -3043,12 +3043,7 @@ void JAttachment::dropDatabase(CheckStatusWrapper* user_status)

 				const PathName& file_name = attachment->att_filename;

-				if (!attachment->locksmith(tdbb, DROP_DATABASE))
-				{
-					ERR_post(Arg::Gds(isc_no_priv) << Arg::Str("drop") <<
-													  Arg::Str("database") <<
-													  Arg::Str(file_name));
-				}
+				SCL_check_database(tdbb, SCL_drop);

 				if (attachment->att_flags & ATT_shutdown)
 				{
diff --git a/src/jrd/scl.epp b/src/jrd/scl.epp
index 466c401c17a..9da863c8419 100644
--- a/src/jrd/scl.epp
+++ b/src/jrd/scl.epp
@@ -372,6 +372,9 @@ void SCL_check_database(thread_db* tdbb, SecurityClass::flags_t mask)
 	if (mask == SCL_alter && attachment->locksmith(tdbb, USE_NBACKUP_UTILITY))
 		return;

+	if (mask == SCL_drop && attachment->locksmith(tdbb, DROP_DATABASE))
+		return;
+
 	const P_NAMES* names;
 	for (names = p_names; names->p_names_priv; names++)
 	{

problem_statement:
User with DROP DATABASE privilege can't drop database [CORE5790]

Submitted by: @romansimakov

isql \-u sysdba \-p masterkey
create database 'localhost:d:\\db\\test\.fdb';
create user user1 password 'pass';
grant drop database to user1;

isql \-u user1 \-p pass
connect 'localhost:d:\\db\\test\.fdb';
drop database;

Statement failed, SQLSTATE = 28000
no permission for drop access to database D:\\DB\\WWW\.FDB

